<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Dustline Yard: a three.js tactical FPS</title>
<style>
  /* Look plan: canvas, surface, hairline, ink, muted and one accent. Every colour below is one of the six. */
  :root {
