  #banner[hidden] { display: none; }
  #banner-title { font-size: 44px; font-weight: 500; letter-spacing: -0.02em; margin: 0; }
  #banner-sub { font-size: 16px; color: var(--muted); margin: 8px 0 0; }

  #buy {
    position: fixed;
    left: 50%;
