    font-size: 12px;
    text-align: center;
  }
  #buy-close { margin-top: 16px; width: 100%; padding: 10px; border: 1px solid var(--accent); border-radius: var(--radius-control); background: var(--accent); color: var(--canvas); font: inherit; font-weight: 500; cursor: pointer; }

  .overlay {
    position: fixed;
    inset: 0;
    display: grid;
    place-items: center;
    padding: 24px;
    background: color-mix(in srgb, var(--canvas) 86%, transparent);
  }
  .overlay[hidden] { display: none; }
  .panel {
    width: min(460px, 100%);
    padding: 32px;
    background: var(--surface);
    border: 1px solid var(--hairline);
